function coverageTileClass(t) {
  return t.status === 'source_guidance' ? 'topic-ok' : t.status === 'missing' ? 'topic-missing' : 'topic-review';
}

// Day-differences between YYYY-MM-DD strings, so GMT-checked evidence reads
// naturally without inventing an hour of the day.
function relDate(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso || '')) return '';
  const days = Math.round((Date.parse(iso) - Date.parse(new Date().toISOString().slice(0, 10))) / 86400000);
  if (days === 0) return 'today';
  const s = Math.abs(days) === 1 ? 'day' : 'days';
  return days > 0 ? `in ${days} ${s}` : `${-days} ${s} ago`;
}

// One compact chip summarizing how fresh the quoted evidence is.
function freshnessChip(sources) {
  if (!sources.length) return null;
  const checkedAt = sources.map(s => s.checkedAt).filter(Boolean).sort()[0];
  const expiresAt = sources.map(s => s.expiresAt).filter(Boolean).sort()[0];
  if (!checkedAt && !expiresAt) return null;
  const parts = [];
  if (checkedAt) parts.push(`Oldest source check ${checkedAt}`);
  if (expiresAt) parts.push(`expire ${expiresAt}`);
  // Same UTC calendar-day math as relDate(), so the chip and the source
  // lines never disagree by a day border.
  const days = expiresAt ? Math.round((Date.parse(expiresAt) - Date.parse(new Date().toISOString().slice(0, 10))) / 86400000) : Infinity;
  return el('span', parts.join(' · '), `fresh-chip${days <= 7 ? ' fresh-soon' : ''}`);
}

// Honest "why this answer" panel built from the retrieval diagnostics the
// engine already returns on /v1/answers.
function retrievalPanel(retrieval) {
  if (!retrieval?.candidates?.length) return null;
  const details = el('details', undefined, 'retrieval');
  details.append(el('summary', 'How was this answer chosen?'));
  details.append(el('p', `Keyword ranking (${retrieval.version}): higher scores mean closer keyword and scope matches.`, 'muted'));
  retrieval.candidates.slice(0, 8).forEach(c => {
    const row = el('div', undefined, 'source');
    row.append(el('strong', c.id));
    const terms = c.matchedTerms?.length ? c.matchedTerms.join(', ') : 'no keyword match';
    const score = typeof c.score === 'number' ? c.score.toFixed(3) : c.score;
    row.append(el('small', `score ${score} · ${terms} · ${c.available ? 'eligible for selection' : 'unavailable'}`));
    if (!c.available) row.append(el('p', humanizeGap(c.reason), 'muted'));
    details.append(row);
  });
  return details;
}

function el(tag, text, cls) {
  const n = document.createElement(tag);
  if (text !== undefined) n.textContent = text;
  if (cls) n.className = cls;
  return n;
}

function link(title, url) {
  const a = el('a', title);
  a.href = url;
  a.target = '_blank';
  a.rel = 'noopener noreferrer';
  return a;
}

const statusLive = el('div', '', 'sr-only');
statusLive.setAttribute('aria-live', 'polite');
statusLive.setAttribute('aria-atomic', 'true');
document.body.appendChild(statusLive);

function announce(msg) {
  statusLive.textContent = msg;
  setTimeout(() => { statusLive.textContent = ''; }, 1000);
}

function spinner() {
  const s = el('div', '', 'spinner');
  s.setAttribute('aria-hidden', 'true');
  s.innerHTML = '<span class="spinner-dot"></span><span class="spinner-dot"></span><span class="spinner-dot"></span><span class="spinner-dot"></span>';
  return s;
}

// Rebuilds the submit button exactly as written in index.html (text node + arrow span).
function resetAskButton(button) {
  button.disabled = false;
  button.classList.remove('disabled');
  button.textContent = '';
  button.append(document.createTextNode(ASK_LABEL), el('span', '↗'));
}

// Neutral placeholders while a request is in flight, so a previous answer
// never lingers next to a newer question. An elapsed-time counter helps when
// the optional AI review path runs long.
let pendingTimer = null;
function clearPendingTimer() {
  if (pendingTimer) { clearInterval(pendingTimer); pendingTimer = null; }
}
function pendingAnswer() {
  clearPendingTimer();
  const box = el('article', undefined, 'result pending');
  const status = el('span', 'Checking sources for your question…', 'status');
  // The elapsed-time updates announce politely without stealing focus.
  status.setAttribute('role', 'status');
  box.append(status);
  const started = Date.now();
  pendingTimer = setInterval(() => {
    status.textContent = `Checking sources for your question… ${Math.round((Date.now() - started) / 1000)}s elapsed`;
  }, 1000);
  box.append(el('div', undefined, 'skeleton skeleton-badge'));
  box.append(el('div', undefined, 'skeleton skeleton-heading'));
  box.append(el('div', undefined, 'skeleton skeleton-para'));
  box.append(el('div', undefined, 'skeleton skeleton-line'));
  box.append(el('div', undefined, 'skeleton skeleton-line short'));
  const card = el('div', undefined, 'skeleton-card');
  card.append(el('div', undefined, 'skeleton skeleton-line short'));
  card.append(el('div', undefined, 'skeleton skeleton-line'));
  box.append(card);
  return box;
}

async function api(path, data, token) {
  const headers = {};
  if (data) headers['Content-Type'] = 'application/json';
  if (token) headers['Authorization'] = `Bearer ${token}`;
  const r = await fetch(path, {
    method: data ? 'POST' : 'GET',
    headers,
    body: data ? JSON.stringify(data) : undefined
  });
  let body;
  try {
    body = await r.json();
  } catch {
    if (!r.ok) throw new Error(`Server error ${r.status}`);
    throw new Error('Unexpected server response');
  }
  if (!r.ok) {
    const err = new Error(body?.error || 'Request failed');
    err.status = r.status;
    err.code = body?.code;
    err.requestId = r.headers.get('X-Request-ID');
    // The server supplies a Retry-After hint on 429; keep it for the countdown.
    const retryAfter = Number(r.headers.get('Retry-After'));
    if (r.status === 429 && retryAfter > 0) err.retryAfterSeconds = retryAfter;
    throw err;
  }
  return body;
}

document.querySelectorAll('[data-view]').forEach(b => b.addEventListener('click', async () => {
  document.querySelectorAll('.view').forEach(v => v.hidden = v.id !== b.dataset.view);
  document.querySelectorAll('.nav').forEach(n => {
    n.classList.toggle('active', n === b);
    if (n === b) n.setAttribute('aria-current', 'page');
    else n.removeAttribute('aria-current');
  });
  currentView = b.dataset.view;
  document.title = titleFor(currentView);
  // Switching views stops any in-flight read-aloud so audio never drags on.
  if ('speechSynthesis' in window) speechSynthesis.cancel();
  // Announce the new view to screen readers by moving focus to its heading.
  const heading = $(`#${b.dataset.view} h1`);
  if (heading) heading.focus();
  if (typeof syncSidebarActiveView === 'function') syncSidebarActiveView(b.dataset.view);
  if (typeof initViewToolSwitchers === 'function') initViewToolSwitchers(); // re-check dynamic views
  if (b.dataset.view === 'binder') renderBinder();
  if (b.dataset.view === 'airport') renderAirportKit();
  if (b.dataset.view === 'pathway') renderPathway();
  if (b.dataset.view === 'cashflow') renderCashflow();
  if (b.dataset.view === 'tenancy') renderTenancyWizard();
  if (b.dataset.view === 'journey') renderJourneyRoadmap();
  if (b.dataset.view === 'tax') renderTaxEngine();
  if (b.dataset.view === 'forms') renderFormsSuite();
  if (b.dataset.view === 'paycheck') renderPaycheckSimulator();
  if (b.dataset.view === 'banking') renderBanking();
  if (b.dataset.view === 'driving') renderDriving();
  if (b.dataset.view === 'careers') renderCareersSuite();
  if (b.dataset.view === 'healthcare') renderHealthcareSuite();
  if (b.dataset.view === 'coverage') await loadCoverage();
}));

