function setupCraBenefitsCalculator() {
  const btn = $('#cra-calc-btn');
  if (!btn) return;

  const dateInput = $('#cra-calc-date');
  if (dateInput && !dateInput.value) {
    dateInput.value = new Date().toISOString().slice(0, 10);
  }

  const runCalc = async () => {
    const resContainer = $('#cra-calc-results');
    if (!resContainer) return;
    resContainer.innerHTML = '<p class="muted">Calculating statutory CRA credits and compiling filing packet...</p>';

    const province = $('#cra-calc-province')?.value || 'ON';
    const income = Number($('#cra-calc-income')?.value || 32000);
    const marital = $('#cra-calc-marital')?.value || 'married';
    const under6 = Number($('#cra-calc-under6')?.value || 0);
    const over6 = Number($('#cra-calc-over6')?.value || 0);
    const landingDateStr = $('#cra-calc-date')?.value || new Date().toISOString().slice(0, 10);

    try {
      const res = await fetch('/v1/tools/cra-benefits', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          province,
          adjustedFamilyNetIncomeCad: income,
          maritalStatus: marital,
          childrenUnder6Count: under6,
          children6to17Count: over6,
          landingDateStr
        })
      });
      if (!res.ok) throw new Error('API request failed');
      const data = await res.json();
      renderCraBenefitsAssessment(data, resContainer);
    } catch {
      resContainer.innerHTML = '<div class="alert-box error"><p>Failed to calculate CRA newcomer benefits. Please retry.</p></div>';
    }
  };

  btn.addEventListener('click', runCalc);
}

function renderLeaseGuardAssessment(data, container) {
  if (!container) return;
  const { province, overallSafetyRating, standardFormStatus, depositAudit, clauseAudits, officialDisputeNotice, statutoryAuthority } = data;

  const isRisk = overallSafetyRating === 'high_risk';
  const isWarn = overallSafetyRating === 'warning';
  const badgeColor = isRisk ? '#ef4444' : isWarn ? '#f59e0b' : '#10b981';
  const badgeBg = isRisk ? '#fee2e2' : isWarn ? '#fef3c7' : '#d1fae5';
  const ratingText = isRisk ? 'CRITICAL RISKS & ILLEGAL DEMANDS' : isWarn ? 'WARNINGS DETECTED' : 'STANDARD LAWFUL LEASE';

  const fmt = (n) => '$' + Number(n || 0).toLocaleString();

  container.innerHTML = `
    <div style="border:1px solid var(--border);border-radius:8px;padding:1.25rem;background:var(--bg-card, #fff);">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.5rem;margin-bottom:1rem;">
        <div>
          <span class="badge" style="background:${badgeBg};color:${badgeColor};font-weight:700;padding:0.25rem 0.6rem;border-radius:4px;font-size:0.82rem;">${ratingText}</span>
          <h3 style="margin:0.5rem 0 0.2rem 0;font-size:1.25rem;">Lease check (${province})</h3>
          <span style="font-size:0.83rem;color:var(--text-muted);">${statutoryAuthority}</span>
        </div>
        ${depositAudit.totalUnlawfulExcessCad > 0 ? `
          <div style="text-align:right;">
            <div style="font-size:1.3rem;font-weight:700;color:#dc2626;">${fmt(depositAudit.totalUnlawfulExcessCad)} CAD</div>
            <span style="font-size:0.8rem;color:#b91c1c;">Unlawful Deposit Excess</span>
          </div>
        ` : ''}
      </div>

      ${standardFormStatus.statutoryRemedy ? `
        <div style="padding:0.85rem;background:#fff1f2;border-left:4px solid #f43f5e;border-radius:4px;margin-bottom:1rem;font-size:0.86rem;line-height:1.45;">
          <strong style="color:#be123c;">⚠️ NON-STANDARD LEASE USED:</strong><br>
          ${standardFormStatus.statutoryRemedy.demandRight}<br>
          <span style="display:inline-block;margin-top:0.35rem;color:#9f1239;"><strong>Withholding rent (Ontario rule):</strong> ${standardFormStatus.statutoryRemedy.rentWithholding} ${standardFormStatus.statutoryRemedy.permanentRetention}</span>
        </div>
      ` : ''}

      ${depositAudit.unlawfulCharges.length > 0 ? `
        <h4 style="margin:1rem 0 0.4rem 0;font-size:0.95rem;color:#b91c1c;">🚨 Unlawful Deposit Demands:</h4>
        <div style="display:flex;flex-direction:column;gap:0.4rem;margin-bottom:1rem;">
          ${depositAudit.unlawfulCharges.map(ch => `
            <div style="padding:0.6rem 0.75rem;background:#fef2f2;border:1px solid #fecaca;border-radius:6px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.5rem;font-size:0.85rem;">
              <span>${ch.description}</span>
              <strong style="color:#dc2626;">+${fmt(ch.unlawfulAmountCad)} Illegal Excess</strong>
            </div>
          `).join('')}
        </div>
      ` : ''}

      ${clauseAudits.length > 0 ? `
        <h4 style="margin:1rem 0 0.4rem 0;font-size:0.95rem;">⚖️ Clause Enforceability Rulings:</h4>
        <div style="display:flex;flex-direction:column;gap:0.5rem;margin-bottom:1.25rem;">
          ${clauseAudits.map(cl => `
            <div style="padding:0.75rem;background:var(--bg-elevated, #f8fafc);border:1px solid #e2e8f0;border-left:4px solid ${cl.isLegal ? '#10b981' : '#f59e0b'};border-radius:4px;font-size:0.85rem;">
              <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:0.25rem;">
                <strong>${cl.name}</strong>
                <span class="badge" style="font-size:0.75rem;background:${cl.isLegal ? '#d1fae5' : '#fef3c7'};color:${cl.isLegal ? '#065f46' : '#92400e'};">${cl.statutoryStatus.toUpperCase()} (${cl.statute})</span>
              </div>
              <p style="margin:0.35rem 0 0.2rem 0;color:var(--text);">${cl.ruling}</p>
              <div style="font-size:0.8rem;color:var(--text-muted);">${cl.action}</div>
            </div>
          `).join('')}
        </div>
      ` : ''}

      <div style="margin-top:1.25rem;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.5rem;">
          <h4 style="margin:0;font-size:0.95rem;">📋 Formal Dispute Notice to Landlord:</h4>
          <button type="button" class="sos-copy-btn" id="lease-guard-copy-btn" style="padding:0.25rem 0.6rem;font-size:0.8rem;">Copy Letter 📋</button>
        </div>
        <textarea id="lease-guard-letter-text" readonly rows="7" style="width:100%;border-radius:6px;border:1px solid var(--border);padding:0.75rem;font-family:monospace;font-size:0.8rem;background:var(--bg-elevated);color:var(--text);">${escapeHtml(officialDisputeNotice)}</textarea>
      </div>
    </div>
  `;

  const copyBtn = $('#lease-guard-copy-btn');
  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      const txt = $('#lease-guard-letter-text')?.value;
      if (txt) {
        navigator.clipboard?.writeText(txt).then(() => {
          copyBtn.textContent = 'Copied! ✓';
          setTimeout(() => { copyBtn.textContent = 'Copy Letter 📋'; }, 2000);
        });
      }
    });
  }
}

function setupLeaseGuard() {
  const btn = $('#lease-guard-calc-btn');
  if (!btn) return;

  const runAudit = async () => {
    const resContainer = $('#lease-guard-result');
    if (!resContainer) return;
    resContainer.innerHTML = '<p class="muted">Checking your lease against tenancy rules…</p>';

    const province = $('#lease-guard-prov')?.value || 'ON';
    const rent = Number($('#lease-guard-rent')?.value || 2200);
    const standardFormUsed = $('#lease-guard-standard')?.value !== 'no';
    const rentDepositMonths = Number($('#lease-guard-rent-months')?.value || 1);
    const damageDepositCad = Number($('#lease-guard-damage-dep')?.value || 0);
    const keyDepositCad = Number($('#lease-guard-key-dep')?.value || 50);
    const customClauseText = $('#lease-guard-custom-text')?.value || '';

    const clausesPresent = [];
    if ($('#lease-clause-pets')?.checked) clausesPresent.push('no_pets');
    if ($('#lease-clause-guests')?.checked) clausesPresent.push('no_guests');
    if ($('#lease-clause-cheques')?.checked) clausesPresent.push('post_dated_cheques');
    if ($('#lease-clause-repairs')?.checked) clausesPresent.push('tenant_repairs');
    if ($('#lease-clause-lockout')?.checked) clausesPresent.push('lockout_clause');

    try {
      const res = await fetch('/v1/tools/lease-guard', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          province,
          monthlyRentCad: rent,
          standardFormUsed,
          depositDemands: { rentDepositMonths, damageDepositCad, keyDepositCad },
          clausesPresent,
          customClauseText
        })
      });
      if (!res.ok) throw new Error('API request failed');
      const data = await res.json();
      renderLeaseGuardAssessment(data, resContainer);
    } catch {
      resContainer.innerHTML = '<div class="alert-box error"><p>We could not check your lease. Please try again.</p></div>';
    }
  };

  btn.addEventListener('click', runAudit);
}

