          currentlyWorkingForBcEmployer: worksBc,
          educationLevel: edu,
          completedBcEducation: bcEdu,
          clbLevel: clb,
          isBilingualEnglishAndFrench: bilingual,
          jobLocationArea: area,
          familySize,
