function renderEiDisqualificationAssessment(data, container) {
  const {
    applicantName,
    regularBenefits,
    justCauseAudit,
    misconductAudit,
    separationMoniesAllocation,
    specialBenefitsOverride,
    defenseArguments,
    statutoryNotes,
    riskWarnings
  } = data;

  const isDisqualified = regularBenefits?.isDisqualifiedFromRegularBenefits;
  const statusClass = isDisqualified ? 'error' : 'success';
  const statusTitle = isDisqualified ? 'Indefinite EI Regular Benefits Disqualification' : 'Eligible for Regular Benefits';

  let html = `
    <div class="alert-box ${statusClass}">
      <h4>${statusTitle}</h4>
      <p><strong>Claimant:</strong> ${applicantName} | <strong>Weekly Benefit:</strong> ${regularBenefits?.estimatedWeeklyBenefitCad?.toFixed(2) || '0.00'} CAD</p>
      <p>${regularBenefits?.disqualificationReason}</p>
    </div>

    <div class="u-stat-grid u-mt-100">
      <div class="stat-card">
        <span class="stat-val">${regularBenefits?.insurableHoursAccumulated || 0} hrs</span>
        <span class="stat-lbl">Insurable Hours (${regularBenefits?.meetsHoursThreshold ? 'Meets Threshold' : 'Shortfall'})</span>
      </div>
      <div class="stat-card">
        <span class="stat-val">${separationMoniesAllocation?.estimatedAllocationDelayWeeks || 0} wks</span>
        <span class="stat-lbl">Severance Allocation Delay</span>
      </div>
      <div class="stat-card">
        <span class="stat-val">${justCauseAudit?.justCauseEstablished ? 'Established' : 'None'}</span>
        <span class="stat-lbl">Statutory Just Cause (s. 29(c))</span>
      </div>
    </div>
  `;

  if (separationMoniesAllocation?.totalSeparationMoniesCad > 0) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Separation Monies Allocation (EI Regs ss. 35–36)</h5>
        <p>${separationMoniesAllocation.delayExplanation}</p>
        <p class="u-text-sm muted">Total Separation Pay: ${separationMoniesAllocation.totalSeparationMoniesCad?.toLocaleString()} CAD allocated at normal rate of ${separationMoniesAllocation.normalWeeklyEarningsCad?.toLocaleString()} CAD/week.</p>
      </div>
    `;
  }

  if (misconductAudit?.employerAllegedMisconduct) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Misconduct Audit (Canada v. Brissette Precedent)</h5>
        <p><strong>Finding:</strong> ${misconductAudit.misconductAuditResult === 'incompetence_not_misconduct' ? 'Performance/Incompetence Protected (Not Misconduct)' : 'Misconduct Disqualification Upheld'}</p>
      </div>
    `;
  }

  if (specialBenefitsOverride?.isClaimingSpecialBenefits) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Special Benefits Exemption (EIA s. 33)</h5>
        <p>Disqualification for voluntary leaving or misconduct does not apply to EI sickness, maternity, parental, or caregiving benefits.</p>
      </div>
    `;
  }

  if (defenseArguments?.length) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Statutory Defense Arguments</h5>
        <ul>${defenseArguments.map(d => `<li>${d}</li>`).join('')}</ul>
      </div>
    `;
  }

  if (riskWarnings?.length) {
    html += `
      <div class="alert-box error u-mt-100">
        <h5>Statutory Warnings</h5>
        <ul>${riskWarnings.map(w => `<li>${w}</li>`).join('')}</ul>
      </div>
    `;
  }

  if (statutoryNotes?.length) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Governing Authorities</h5>
        <ul>${statutoryNotes.map(n => `<li>${n}</li>`).join('')}</ul>
      </div>
    `;
  }

  container.innerHTML = html;
}

function setupEiDisqualification() {
  const form = document.querySelector('#ei-disqualification-form');
  const resultsContainer = document.querySelector('#ei-disqualification-results');
  if (!form || !resultsContainer) return;

  const runAudit = async () => {
    const separationType = document.querySelector('#ei-separation-type')?.value || 'voluntary_quit';
    const justCause = document.querySelector('#ei-just-cause')?.value;
    const justCauseReason = justCause !== 'none' ? justCause : null;
    const normalWeeklyGrossEarningsCad = Number(document.querySelector('#ei-weekly-earnings')?.value) || 1200;
    const insurableHoursAccumulated = Number(document.querySelector('#ei-insurable-hours')?.value) || 720;
    const severancePayReceivedCad = Number(document.querySelector('#ei-severance-pay')?.value) || 0;
    const payInLieuOfNoticeCad = Number(document.querySelector('#ei-notice-pay')?.value) || 0;
    const vacationPayPaidOutCad = Number(document.querySelector('#ei-vacation-pay')?.value) || 0;
    const isSpecial = document.querySelector('#ei-special-benefits')?.value === 'true';
    const allegedMisconductType = document.querySelector('#ei-misconduct-type')?.value || 'incompetence_performance';
    const triedReasonableAlternatives = document.querySelector('#ei-tried-alternatives')?.checked ?? true;
    const employerAllegedMisconduct = document.querySelector('#ei-alleged-misconduct')?.checked ?? false;

    try {
      const res = await fetch('/v1/tools/ei-disqualification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          separationType,
          justCauseReason,
          triedReasonableAlternatives,
          employerAllegedMisconduct,
          allegedMisconductType,
          normalWeeklyGrossEarningsCad,
          insurableHoursAccumulated,
          severancePayReceivedCad,
          payInLieuOfNoticeCad,
          vacationPayPaidOutCad,
          isClaimingSpecialBenefits: isSpecial
        })
      });
      if (!res.ok) throw new Error('Failed to evaluate EI disqualification');
      const data = await res.json();
      renderEiDisqualificationAssessment(data, resultsContainer);
    } catch {
      resultsContainer.innerHTML = '<div class="alert-box error"><p>Failed to evaluate EI disqualification. Please retry.</p></div>';
    }
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    runAudit();
  });

  autoRun(runAudit, form);
}

