function renderSpeculationTaxAssessment(data, container) {
  const {
    province,
    propertyValuationCad,
    isTaxExempt,
    applicableExemption,
    taxRatePercent,
    grossTaxPayableCad,
    netTaxPayableCad,
    ontarioNrstRebate,
    statutoryNotes,
    riskWarnings,
    actionPlan
  } = data;

  const statusClass = isTaxExempt || ontarioNrstRebate?.isNrstRebateEligible ? 'success' : 'warning';
  const statusTitle = province === 'BC'
    ? (isTaxExempt ? 'Statutory SVT Exemption Qualified' : `Speculation Tax Payable (${taxRatePercent}% Rate)`)
    : (ontarioNrstRebate?.isNrstRebateEligible ? 'Ontario NRST 25% Rebate Approved' : 'NRST Payable / Rebate Ineligible');

  let html = `
    <div class="alert-box ${statusClass}">
      <h4>${statusTitle}</h4>
      <p><strong>Province:</strong> ${province} | <strong>Valuation:</strong> ${propertyValuationCad?.toLocaleString()} CAD | <strong>Net Tax Payable:</strong> ${netTaxPayableCad?.toLocaleString()} CAD</p>
      ${applicableExemption ? `<p><strong>Exemption / Category:</strong> ${applicableExemption}</p>` : ''}
    </div>

    <div class="u-stat-grid u-mt-100">
      <div class="stat-card">
        <span class="stat-val">${taxRatePercent}%</span>
        <span class="stat-lbl">Statutory Tax Rate</span>
      </div>
      <div class="stat-card">
        <span class="stat-val">${grossTaxPayableCad?.toLocaleString()} CAD</span>
        <span class="stat-lbl">Gross Tax Calculated</span>
      </div>
      <div class="stat-card">
        <span class="stat-val">${(ontarioNrstRebate?.nrstRebateAmountCad || 0).toLocaleString()} CAD</span>
        <span class="stat-lbl">NRST Rebate Claimable</span>
      </div>
    </div>
  `;

  if (province === 'ON' && ontarioNrstRebate) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Ontario Non-Resident Speculation Tax (NRST) Rebate Audit</h5>
        <p>${ontarioNrstRebate.nrstRebateReason}</p>
        <p class="u-text-sm muted">Statutory Limits: PR acquired within ${ontarioNrstRebate.prAcquisitionWindowDays} days of closing; rebate filed within ${ontarioNrstRebate.claimLimitationDays} days of PR status.</p>
      </div>
    `;
  }

  if (actionPlan?.length) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Statutory Action Plan</h5>
        <ol>${actionPlan.map(a => `<li>${a}</li>`).join('')}</ol>
      </div>
    `;
  }

  if (riskWarnings?.length) {
    html += `
      <div class="alert-box error u-mt-100">
        <h5>Statutory Warnings</h5>
        <ul>${riskWarnings.map(w => `<li>${w}</li>`).join('')}</ul>
      </div>
    `;
  }

  if (statutoryNotes?.length) {
    html += `
      <div class="info-card u-mt-100">
        <h5>Governing Legislation</h5>
        <ul>${statutoryNotes.map(n => `<li>${n}</li>`).join('')}</ul>
      </div>
    `;
  }

  container.innerHTML = html;
}

function setupSpeculationTax() {
  const form = document.querySelector('#speculation-tax-form');
  const resultsContainer = document.querySelector('#speculation-tax-results');
  if (!form || !resultsContainer) return;

  const runAudit = async () => {
    const province = document.querySelector('#st-province')?.value || 'BC';
    const propertyAssessedValueCad = Number(document.querySelector('#st-property-value')?.value) || 1200000;
    const purchasePriceCad = propertyAssessedValueCad;
    const isCanadianCitizenOrPr = document.querySelector('#st-status')?.value === 'citizen_pr';
    const rentalDaysInYear = Number(document.querySelector('#st-rental-days')?.value) || 0;
    const purchaseClosingDate = document.querySelector('#st-closing-date')?.value || '2026-01-15';
    const prDateVal = document.querySelector('#st-pr-date')?.value;
    const prStatusAcquiredDate = prDateVal ? prDateVal : null;
    const rebateApplicationDate = document.querySelector('#st-claim-date')?.value || '2026-04-01';
    const isPrincipalResidenceOccupied6Months = document.querySelector('#st-primary-home')?.checked ?? true;
    const isSatelliteFamily = document.querySelector('#st-satellite-family')?.checked ?? false;
    const isYearOfPurchase = document.querySelector('#st-year-purchased')?.checked ?? false;
    const occupiedAsPrincipalResidenceWithin60Days = document.querySelector('#st-occupied-60')?.checked ?? true;
    const heldSolelyWithSpouse = document.querySelector('#st-held-solely')?.checked ?? true;

    try {
      const res = await fetch('/v1/tools/speculation-tax-rebate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          province,
          propertyAssessedValueCad,
          purchasePriceCad,
          isCanadianCitizenOrPr,
          rentalDaysInYear,
          purchaseClosingDate,
          prStatusAcquiredDate,
          rebateApplicationDate,
          isPrincipalResidenceOccupied6Months,
          isSatelliteFamily,
          isYearOfPurchase,
          occupiedAsPrincipalResidenceWithin60Days,
          heldSolelyWithSpouse
        })
      });
      if (!res.ok) throw new Error('Failed to evaluate Speculation Tax');
      const data = await res.json();
      renderSpeculationTaxAssessment(data, resultsContainer);
    } catch {
      resultsContainer.innerHTML = '<div class="alert-box error"><p>Failed to evaluate Speculation Tax. Please retry.</p></div>';
    }
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    runAudit();
  });

  autoRun(runAudit, form);
}

